-- Stacko_Concept_Images_Round2.xlsx: 26 library entries (scripts/import/image-batch.py). Idempotent.
do $$
declare v_brand uuid := (select id from public.brands where name = 'Stacko' order by created_at limit 1);
begin
  if v_brand is null then raise exception 'brand not found'; end if;
  insert into public.library_items (brand_id, code, kind, status, title, collection, aspect, prompt, use_for,
    when_to_use, fits_posts, notes, placeholders)
  select v_brand, i.code, i.kind, i.status, left(i.title, 300), i.collection, i.aspect, i.prompt, i.use_for,
    i.when_to_use, i.fits_posts, i.notes, i.placeholders
  from jsonb_to_recordset($lib$[{"code": "OB-07", "kind": "post_image", "status": "approved", "title": "Compass whose needle points at one glowing box", "collection": "Concept", "aspect": "4:5 vertical", "prompt": "A large brushed-steel compass lying on the floor, its needle pointing firmly at a single small cardboard box that glows softly teal from inside, a few plain boxes scattered in the soft-focus background. Composition: compass in the lower-left, glowing box lower-right; leave the top 40% empty. Style: photoreal 3D product render, seamless dark navy studio backdrop, glossy dark floor with soft reflections, studio light, sharp focus. Light & colour: cool blue tones, deep navy #0E2440 shadows, soft blue #79C0DE fills, teal #2EF2EE glow only where stated; no orange, yellow or red. Avoid: any text, letters, numbers, logos, labels, tape markings, signage, watermarks, UI content.", "use_for": "\"Where is it?\" posts, search, finding stock", "when_to_use": "Any time", "fits_posts": "IDEA-089, IDEA-090; IDEA-089, IDEA-090", "notes": "Theme: Dark", "placeholders": null}, {"code": "OB-08", "kind": "post_image", "status": "approved", "title": "Iceberg of boxes: a few above water, a huge mass below", "collection": "Concept", "aspect": "4:5 vertical", "prompt": "A split-level view of calm dark water: above the waterline a small neat pile of cardboard boxes floats like the tip of an iceberg; below the waterline, seen through clear blue water, a huge mass of boxes stacked into an iceberg shape fades into the deep, faint teal light from below. Composition: waterline at 45% height, tip centred; keep the sky above the tip empty. Style: photoreal 3D render, half-underwater camera, cinematic. Light & colour: cool blue tones, deep navy #0E2440 shadows, soft blue #79C0DE fills, teal #2EF2EE glow only where stated; no orange, yellow or red. Avoid: any text, letters, numbers, logos, labels, tape markings, signage, watermarks, UI content.", "use_for": "Hidden stock, hidden costs, \"the tip of the problem\"", "when_to_use": "Any time", "fits_posts": "IDEA-091, IDEA-092; IDEA-091, IDEA-092", "notes": "Theme: Dark", "placeholders": null}, {"code": "OB-09", "kind": "post_image", "status": "approved", "title": "Row of box dominoes falling, stopped by one glowing block", "collection": "Concept", "aspect": "4:5 vertical", "prompt": "A long curved row of tall, thin cardboard boxes standing like dominoes on a glossy dark floor; the first half are falling into each other, and the chain is stopped by one solid block glowing softly teal. Composition: row curves from the back-left to the front-right through the lower 55%; top 40% empty. Style: photoreal 3D product render, seamless dark navy studio backdrop, glossy dark floor with soft reflections, studio light, sharp focus. Light & colour: cool blue tones, deep navy #0E2440 shadows, soft blue #79C0DE fills, teal #2EF2EE glow only where stated; no orange, yellow or red. Avoid: any text, letters, numbers, logos, labels, tape markings, signage, watermarks, UI content.", "use_for": "One missed log causes a chain; alerts stop it", "when_to_use": "Any time; good as a reel", "fits_posts": "IDEA-093, IDEA-094; IDEA-093, IDEA-094", "notes": "Theme: Dark", "placeholders": null}, {"code": "OB-10", "kind": "post_image", "status": "approved", "title": "Lighthouse built from stacked boxes beaming teal light", "collection": "Concept", "aspect": "4:5 vertical", "prompt": "A tall lighthouse built entirely from neatly stacked cardboard boxes, standing on dark rocks by a calm night sea, its top lamp glowing teal and casting a soft beam across the water and mist. Composition: lighthouse on the right third, beam sweeping across the top-left; the top-left area is dark sky for text. Style: photoreal 3D render, cinematic night scene, light mist. Light & colour: cool blue tones, deep navy #0E2440 shadows, soft blue #79C0DE fills, teal #2EF2EE glow only where stated; no orange, yellow or red. Avoid: any text, letters, numbers, logos, labels, tape markings, signage, watermarks, UI content.", "use_for": "Visibility, guidance, \"always in sight\"", "when_to_use": "Any time; strong brand image", "fits_posts": "IDEA-095, IDEA-096; IDEA-095, IDEA-096", "notes": "Theme: Dark", "placeholders": null}, {"code": "OB-11", "kind": "post_image", "status": "approved", "title": "Snow globe with a miniature warehouse and tiny boxes inside", "collection": "Concept", "aspect": "4:5 vertical", "prompt": "A glass snow globe on a dark glossy surface; inside it a detailed miniature modern warehouse with a tiny white truck and tiny stacked boxes, soft white snow drifting, faint teal light from the warehouse doors. Composition: globe centred in the lower 60%; top 35% empty dark navy. Style: photoreal 3D product render, seamless dark navy studio backdrop, glossy dark floor with soft reflections, studio light, sharp focus. Light & colour: cool blue tones, deep navy #0E2440 shadows, soft blue #79C0DE fills, teal #2EF2EE glow only where stated; no orange, yellow or red. Avoid: any text, letters, numbers, logos, labels, tape markings, signage, watermarks, UI content.", "use_for": "December posts, holiday greetings, \"whole warehouse in your hand\"", "when_to_use": "1–24 Dec 2026", "fits_posts": "IDEA-097, IDEA-098; IDEA-097, IDEA-098", "notes": "Theme: Dark", "placeholders": null}, {"code": "OB-12", "kind": "post_image", "status": "approved", "title": "Telescope aimed at a distant floating container", "collection": "Concept", "aspect": "4:5 vertical", "prompt": "A sleek white telescope on a tripod on a dark rooftop at night, pointed at a single shipping container floating far away in a deep blue starry sky, the container softly lit teal. Composition: telescope in the lower-left, container small in the upper-right; the centre-top is empty sky for text. Style: photoreal 3D render, cinematic night, fine star field. Light & colour: cool blue tones, deep navy #0E2440 shadows, soft blue #79C0DE fills, teal #2EF2EE glow only where stated; no orange, yellow or red. Avoid: any text, letters, numbers, logos, labels, tape markings, signage, watermarks, UI content.", "use_for": "Imports, tracking shipments far away", "when_to_use": "Any time", "fits_posts": "IDEA-099, IDEA-100; IDEA-099, IDEA-100", "notes": "Theme: Dark", "placeholders": null}, {"code": "OB-13", "kind": "post_image", "status": "approved", "title": "Puzzle cube made of cardboard faces, one face glowing teal", "collection": "Concept", "aspect": "4:5 vertical", "prompt": "A large 3x3 twisty puzzle cube made of small cardboard box faces, slightly twisted mid-turn, with one complete face lit from within by soft teal light, on a glossy dark floor. Composition: cube centred in the lower 60%, three-quarter view; top 35% empty. Style: photoreal 3D product render, seamless dark navy studio backdrop, glossy dark floor with soft reflections, studio light, sharp focus. Light & colour: cool blue tones, deep navy #0E2440 shadows, soft blue #79C0DE fills, teal #2EF2EE glow only where stated; no orange, yellow or red. Avoid: any text, letters, numbers, logos, labels, tape markings, signage, watermarks, UI content.", "use_for": "Complexity solved, \"many warehouses, one picture\"", "when_to_use": "Any time; echoes the logo cube", "fits_posts": "IDEA-101, IDEA-102; IDEA-101, IDEA-102", "notes": "Theme: Dark", "placeholders": null}, {"code": "OB-14", "kind": "post_image", "status": "approved", "title": "Balance scale with boxes perfectly level", "collection": "Concept", "aspect": "4:5 vertical", "prompt": "A minimal modern balance scale in white and soft blue, with a small stack of cardboard boxes on each pan, perfectly level, a tiny teal glow at the central pivot. Composition: scale centred in the lower 60%; top 35% clean pale background. Style: photoreal 3D product render, seamless pale blue-white studio (#F4F8FA), soft daylight, gentle shadows, sharp focus. Light & colour: cool blue tones, deep navy #0E2440 shadows, soft blue #79C0DE fills, teal #2EF2EE glow only where stated; no orange, yellow or red. Avoid: any text, letters, numbers, logos, labels, tape markings, signage, watermarks, UI content.", "use_for": "Rebalancing stock between branches, fairness, control", "when_to_use": "Any time", "fits_posts": "IDEA-103, IDEA-104; IDEA-103, IDEA-104", "notes": "Theme: Light", "placeholders": null}, {"code": "OB-15", "kind": "post_image", "status": "approved", "title": "Maze made of cardboard walls with one glowing path", "collection": "Concept", "aspect": "4:5 vertical", "prompt": "Top-down view of a maze built from flat cardboard walls on a pale blue-white floor, with one clear path from the entrance to the centre traced by a thin line of soft teal light. Composition: maze fills the lower 65% at a slight angle; top 30% clean. Style: photoreal 3D render, top-down at 60°, soft daylight, gentle shadows. Light & colour: cool blue tones, deep navy #0E2440 shadows, soft blue #79C0DE fills, teal #2EF2EE glow only where stated; no orange, yellow or red. Avoid: any text, letters, numbers, logos, labels, tape markings, signage, watermarks, UI content.", "use_for": "Finding your way, onboarding, search", "when_to_use": "Any time", "fits_posts": "IDEA-105, IDEA-106; IDEA-105, IDEA-106", "notes": "Theme: Light", "placeholders": null}, {"code": "OB-16", "kind": "post_image", "status": "approved", "title": "Paper plane folded from cardboard flying over boxes", "collection": "Concept", "aspect": "4:5 vertical", "prompt": "A paper plane folded from thin brown cardboard gliding through the air above a neat row of cardboard boxes, a faint teal light trail behind it, dark navy background with soft bokeh. Composition: plane in the upper-middle flying right, boxes along the bottom; the top-left is empty. Style: photoreal 3D render, slight motion blur on the trail, studio. Light & colour: cool blue tones, deep navy #0E2440 shadows, soft blue #79C0DE fills, teal #2EF2EE glow only where stated; no orange, yellow or red. Avoid: any text, letters, numbers, logos, labels, tape markings, signage, watermarks, UI content.", "use_for": "A message is a log, \"send it, it's logged\"", "when_to_use": "Any time; good as a reel", "fits_posts": "IDEA-107, IDEA-108; IDEA-107, IDEA-108", "notes": "Theme: Dark", "placeholders": null}, {"code": "OB-17", "kind": "post_image", "status": "approved", "title": "Cardboard box with a teal pulse line running across it", "collection": "Concept", "aspect": "4:5 vertical", "prompt": "A single closed cardboard box on a glossy dark floor with a thin glowing teal heartbeat-style pulse line running horizontally through the air and across its front face, continuing into the darkness on both sides. Composition: box centred in the lower half; top 40% empty. Style: photoreal 3D product render, seamless dark navy studio backdrop, glossy dark floor with soft reflections, studio light, sharp focus. Light & colour: cool blue tones, deep navy #0E2440 shadows, soft blue #79C0DE fills, teal #2EF2EE glow only where stated; no orange, yellow or red. Avoid: any text, letters, numbers, logos, labels, tape markings, signage, watermarks, UI content.", "use_for": "Live stock, real-time updates, \"your stock has a pulse\"", "when_to_use": "Any time", "fits_posts": "IDEA-109, IDEA-110; IDEA-109, IDEA-110", "notes": "Theme: Dark", "placeholders": null}, {"code": "OB-18", "kind": "post_image", "status": "approved", "title": "Keyhole in a wall of boxes with teal light shining through", "collection": "Concept", "aspect": "4:5 vertical", "prompt": "A wall made of tightly stacked cardboard boxes in a dark room, with a large classic keyhole shape cut through the middle; bright teal light shines through the keyhole from the other side, casting a keyhole-shaped beam on the floor. Composition: keyhole slightly below centre; top 35% dark and calm. Style: photoreal 3D render, moody, volumetric light. Light & colour: cool blue tones, deep navy #0E2440 shadows, soft blue #79C0DE fills, teal #2EF2EE glow only where stated; no orange, yellow or red. Avoid: any text, letters, numbers, logos, labels, tape markings, signage, watermarks, UI content.", "use_for": "Roles and access, audit trail, \"see inside your stock\"", "when_to_use": "Any time", "fits_posts": "IDEA-111, IDEA-112; IDEA-111, IDEA-112", "notes": "Theme: Dark", "placeholders": null}, {"code": "OB-19", "kind": "post_image", "status": "approved", "title": "Hot-air balloon whose basket is a cardboard box", "collection": "Concept", "aspect": "4:5 vertical", "prompt": "A smooth pale-blue and white hot-air balloon rising into a bright soft sky, its basket replaced by a cardboard box with a few smaller boxes inside, small clouds below. Composition: balloon in the right half, rising; the left half is clean sky for text. Style: photoreal 3D render, airy daylight, soft clouds. Light & colour: cool blue tones, deep navy #0E2440 shadows, soft blue #79C0DE fills, teal #2EF2EE glow only where stated; no orange, yellow or red. Avoid: any text, letters, numbers, logos, labels, tape markings, signage, watermarks, UI content.", "use_for": "Growth, expansion to new cities and the Gulf", "when_to_use": "Any time", "fits_posts": "IDEA-113, IDEA-114; IDEA-113, IDEA-114", "notes": "Theme: Light", "placeholders": null}, {"code": "OB-20", "kind": "post_image", "status": "approved", "title": "Staircase of boxes rising to a glowing top step", "collection": "Concept", "aspect": "4:5 vertical", "prompt": "A staircase made of cardboard boxes of increasing height rising from left to right on a pale studio floor, the top step glowing softly teal from within. Composition: stairs across the lower 60%, rising to the right; top-left 40% clean. Style: photoreal 3D product render, seamless pale blue-white studio (#F4F8FA), soft daylight, gentle shadows, sharp focus. Light & colour: cool blue tones, deep navy #0E2440 shadows, soft blue #79C0DE fills, teal #2EF2EE glow only where stated; no orange, yellow or red. Avoid: any text, letters, numbers, logos, labels, tape markings, signage, watermarks, UI content.", "use_for": "Step-by-step guides, growth stages, resolutions", "when_to_use": "Any time; strong for January", "fits_posts": "IDEA-115, IDEA-116; IDEA-115, IDEA-116", "notes": "Theme: Light", "placeholders": null}, {"code": "OB-21", "kind": "post_image", "status": "approved", "title": "Rocket built from cardboard boxes lifting off", "collection": "Concept", "aspect": "4:5 vertical", "prompt": "A small rocket built from stacked cardboard boxes lifting off a dark launch pad, soft white smoke billowing at the base and a teal glow from the engine, dark navy sky. Composition: rocket centred, rising from the lower third; top 35% empty. Style: photoreal 3D render, cinematic, low angle. Light & colour: cool blue tones, deep navy #0E2440 shadows, soft blue #79C0DE fills, teal #2EF2EE glow only where stated; no orange, yellow or red. Avoid: any text, letters, numbers, logos, labels, tape markings, signage, watermarks, UI content.", "use_for": "Launch announcements, new features, \"Stacko is live\"", "when_to_use": "Launch week and big announcements", "fits_posts": "IDEA-117, IDEA-118; IDEA-117, IDEA-118", "notes": "Theme: Dark", "placeholders": null}, {"code": "OB-22", "kind": "post_image", "status": "approved", "title": "Tangled ball of grey yarn with one straight teal thread pulled free", "collection": "Concept", "aspect": "4:5 vertical", "prompt": "A big tangled ball of grey yarn on a pale blue-white surface, with one thread pulled out of it into a perfectly straight, glowing teal line running to the right edge. Composition: yarn ball in the lower-left, straight thread across the lower right; top 40% clean. Style: photoreal 3D product render, seamless pale blue-white studio (#F4F8FA), soft daylight, gentle shadows, sharp focus. Light & colour: cool blue tones, deep navy #0E2440 shadows, soft blue #79C0DE fills, teal #2EF2EE glow only where stated; no orange, yellow or red. Avoid: any text, letters, numbers, logos, labels, tape markings, signage, watermarks, UI content.", "use_for": "Untangling messy processes: calls, files, chats", "when_to_use": "Any time", "fits_posts": "IDEA-119, IDEA-120; IDEA-119, IDEA-120", "notes": "Theme: Light", "placeholders": null}, {"code": "OB-23", "kind": "post_image", "status": "approved", "title": "Crystal ball with a tiny glowing route map inside", "collection": "Concept", "aspect": "4:5 vertical", "prompt": "A clear crystal ball on a dark metal stand on a glossy dark table; inside it a tiny glowing teal map with route lines and three small warehouse blocks, faint mist inside the glass. Composition: crystal ball centred in the lower 60%; top 35% empty. Style: photoreal 3D product render, seamless dark navy studio backdrop, glossy dark floor with soft reflections, studio light, sharp focus. Light & colour: cool blue tones, deep navy #0E2440 shadows, soft blue #79C0DE fills, teal #2EF2EE glow only where stated; no orange, yellow or red. Avoid: any text, letters, numbers, logos, labels, tape markings, signage, watermarks, UI content.", "use_for": "\"No crystal ball needed\" — knowing, not guessing", "when_to_use": "Any time", "fits_posts": "IDEA-121, IDEA-122; IDEA-121, IDEA-122", "notes": "Theme: Dark", "placeholders": null}, {"code": "OB-24", "kind": "post_image", "status": "approved", "title": "Vault door swinging open on neatly stacked glowing boxes", "collection": "Concept", "aspect": "4:5 vertical", "prompt": "A heavy round steel bank vault door swinging open, revealing neatly stacked cardboard boxes inside lit by a soft teal glow, dark surroundings. Composition: door on the left, glowing boxes centre-right in the lower 60%; top 35% dark. Style: photoreal 3D render, cinematic, dramatic light. Light & colour: cool blue tones, deep navy #0E2440 shadows, soft blue #79C0DE fills, teal #2EF2EE glow only where stated; no orange, yellow or red. Avoid: any text, letters, numbers, logos, labels, tape markings, signage, watermarks, UI content.", "use_for": "Stock is money, protection, audit trail", "when_to_use": "Any time", "fits_posts": "IDEA-123, IDEA-124; IDEA-123, IDEA-124", "notes": "Theme: Dark", "placeholders": null}, {"code": "OB-25", "kind": "post_image", "status": "approved", "title": "Stopwatch resting on top of a cardboard box, blank dial", "collection": "Concept", "aspect": "4:5 vertical", "prompt": "A classic silver stopwatch with a completely blank white dial (no numbers, no marks) resting on top of a closed cardboard box on a glossy dark floor, a soft teal rim light. Composition: box and stopwatch centred in the lower 55%; top 40% empty. Style: photoreal 3D product render, seamless dark navy studio backdrop, glossy dark floor with soft reflections, studio light, sharp focus. Light & colour: cool blue tones, deep navy #0E2440 shadows, soft blue #79C0DE fills, teal #2EF2EE glow only where stated; no orange, yellow or red. Avoid: any text, letters, numbers, logos, labels, tape markings, signage, watermarks, UI content.", "use_for": "\"10 seconds to log a move\", speed", "when_to_use": "Any time", "fits_posts": "IDEA-125, IDEA-126; IDEA-125, IDEA-126", "notes": "Theme: Dark", "placeholders": null}, {"code": "OB-26", "kind": "post_image", "status": "approved", "title": "Bridge made of boxes connecting two cliffs", "collection": "Concept", "aspect": "4:5 vertical", "prompt": "A sturdy arched bridge built from cardboard boxes spanning a gap between two smooth pale stone cliffs, soft clouds below, bright soft sky. Composition: bridge across the middle of the lower half; top 40% clean sky. Style: photoreal 3D render, airy daylight, slightly elevated view. Light & colour: cool blue tones, deep navy #0E2440 shadows, soft blue #79C0DE fills, teal #2EF2EE glow only where stated; no orange, yellow or red. Avoid: any text, letters, numbers, logos, labels, tape markings, signage, watermarks, UI content.", "use_for": "Connecting branches and countries (Lebanon ↔ Gulf)", "when_to_use": "Any time", "fits_posts": "IDEA-127, IDEA-128; IDEA-127, IDEA-128", "notes": "Theme: Light", "placeholders": null}, {"code": "OB-27", "kind": "post_image", "status": "approved", "title": "Flat cardboard sheet folding itself into a box", "collection": "Concept", "aspect": "4:5 vertical", "prompt": "A flat sheet of brown cardboard on a pale studio surface folding itself into a box, mid-fold, the edges lifting in the air with soft teal light along the creases. Composition: object centred in the lower 55%; top 40% clean. Style: photoreal 3D product render, seamless pale blue-white studio (#F4F8FA), soft daylight, gentle shadows, sharp focus. Light & colour: cool blue tones, deep navy #0E2440 shadows, soft blue #79C0DE fills, teal #2EF2EE glow only where stated; no orange, yellow or red. Avoid: any text, letters, numbers, logos, labels, tape markings, signage, watermarks, UI content.", "use_for": "From a flat invoice to real items, onboarding, setup", "when_to_use": "Any time; good as a reel", "fits_posts": "IDEA-129, IDEA-130; IDEA-129, IDEA-130", "notes": "Theme: Light", "placeholders": null}, {"code": "OB-28", "kind": "post_image", "status": "approved", "title": "Mountain made of stacked boxes with a tiny flag on top", "collection": "Concept", "aspect": "4:5 vertical", "prompt": "A mountain peak formed from hundreds of stacked cardboard boxes rising from soft clouds, with a tiny white flag (no symbols) planted on the summit catching a soft teal light. Composition: peak in the centre-right, lower 65%; top-left clean sky. Style: photoreal 3D render, airy daylight, soft clouds. Light & colour: cool blue tones, deep navy #0E2440 shadows, soft blue #79C0DE fills, teal #2EF2EE glow only where stated; no orange, yellow or red. Avoid: any text, letters, numbers, logos, labels, tape markings, signage, watermarks, UI content.", "use_for": "Milestones, year-end, \"you made it\"", "when_to_use": "Dec 2026 – Jan 2027", "fits_posts": "IDEA-131, IDEA-132; IDEA-131, IDEA-132", "notes": "Theme: Light", "placeholders": null}, {"code": "OB-29", "kind": "post_image", "status": "approved", "title": "Haystack of shredded cardboard with a glowing needle", "collection": "Concept", "aspect": "4:5 vertical", "prompt": "A haystack made of shredded brown cardboard strips on a dark glossy floor, with one steel needle partly sticking out of it, glowing bright teal. Composition: haystack in the lower 55%, needle slightly right of centre; top 40% empty. Style: photoreal 3D product render, seamless dark navy studio backdrop, glossy dark floor with soft reflections, studio light, sharp focus. Light & colour: cool blue tones, deep navy #0E2440 shadows, soft blue #79C0DE fills, teal #2EF2EE glow only where stated; no orange, yellow or red. Avoid: any text, letters, numbers, logos, labels, tape markings, signage, watermarks, UI content.", "use_for": "\"Needle in a haystack\", search across thousands of SKUs", "when_to_use": "Any time", "fits_posts": "IDEA-133, IDEA-134; IDEA-133, IDEA-134", "notes": "Theme: Dark", "placeholders": null}, {"code": "OB-30", "kind": "post_image", "status": "approved", "title": "Single empty pallet on a theatre stage under a spotlight", "collection": "Concept", "aspect": "4:5 vertical", "prompt": "An empty wooden pallet alone on a dark theatre stage, a single cool white spotlight from above, heavy navy stage curtains on both sides, dust in the beam. Composition: pallet in the lower-centre; top 40% dark curtain and beam. Style: photoreal, cinematic, wide shot. Light & colour: cool blue tones, deep navy #0E2440 shadows, soft blue #79C0DE fills, teal #2EF2EE glow only where stated; no orange, yellow or red. Avoid: any text, letters, numbers, logos, labels, tape markings, signage, watermarks, UI content.", "use_for": "Out-of-stock drama, lost sales, low-stock alerts", "when_to_use": "Any time; strong before busy seasons", "fits_posts": "IDEA-135, IDEA-136; IDEA-135, IDEA-136", "notes": "Theme: Dark", "placeholders": null}, {"code": "OB-31", "kind": "post_image", "status": "approved", "title": "Box stack whose reflection in a puddle is a glowing map", "collection": "Concept", "aspect": "4:5 vertical", "prompt": "A small stack of cardboard boxes standing on wet dark pavement at night; in the puddle below, the reflection is not of boxes but of a glowing teal route map with small warehouse dots. Composition: boxes in the upper part of the lower half, reflection filling the bottom third; top 35% dark. Style: photoreal 3D render, cinematic, rain-wet ground. Light & colour: cool blue tones, deep navy #0E2440 shadows, soft blue #79C0DE fills, teal #2EF2EE glow only where stated; no orange, yellow or red. Avoid: any text, letters, numbers, logos, labels, tape markings, signage, watermarks, UI content.", "use_for": "\"What you see vs what Stacko sees\"", "when_to_use": "Any time", "fits_posts": "IDEA-137, IDEA-138; IDEA-137, IDEA-138", "notes": "Theme: Dark", "placeholders": null}, {"code": "OB-32", "kind": "post_image", "status": "approved", "title": "Wall of boxes half dark, half lit, with a light switch", "collection": "Concept", "aspect": "4:5 vertical", "prompt": "A wall of neatly stacked cardboard boxes; the left half is in near darkness, the right half softly lit with cool white and teal light, and a simple white wall light switch sits on a box at the boundary, flipped on. Composition: switch at the centre; top 35% calm. Style: photoreal 3D render, dramatic split lighting. Light & colour: cool blue tones, deep navy #0E2440 shadows, soft blue #79C0DE fills, teal #2EF2EE glow only where stated; no orange, yellow or red. Avoid: any text, letters, numbers, logos, labels, tape markings, signage, watermarks, UI content.", "use_for": "Switching on visibility, before/after in one image", "when_to_use": "Any time", "fits_posts": "IDEA-139, IDEA-140; IDEA-139, IDEA-140", "notes": "Theme: Dark", "placeholders": null}]$lib$::jsonb) as i(code text, kind text, status text, title text,
